const followupFor=(complaint:string,severity='')=>{const text=complaint.toLowerCase();const level=severity.toLowerCase();if(/breath|breathing|chest|blue lips|wheez/.test(text))return 'Are you struggling to breathe at rest, or feeling pressure in your chest?';if(/faint|unconscious|collapse|confus|dizz/.test(text))return 'Did you faint, feel unable to stay awake, or suddenly become confused?';if(/blood|bleed|vomit blood|black stool/.test(text))return 'Where is the bleeding, and is it heavy or getting worse?';if(/allerg|swelling|rash|anaphyl/.test(text))return 'Do you have swelling of the lips or face, or any trouble breathing?';if(/pain|ache|hurt/.test(text)&&/severe|sudden|chest|abdomen|head/.test(text))return 'Is the pain sudden or severe, and is it spreading anywhere?';if(/fever|temperature|chill/.test(text)&&/moderate|severe/.test(level))return 'What is the highest temperature you measured, and are you having chills?';if(/head|migraine/.test(text)&&/moderate|severe/.test(level))return 'Where is the headache, and are there vision changes or weakness?';if(/stomach|abdomen|vomit|nausea|diarr/.test(text)&&/moderate|severe/.test(level))return 'Are you able to keep fluids down, and is the pain getting worse?';if(/moderate|severe/.test(level))return 'What is the main change or limitation this symptom is causing in your daily activities?';return null};
