const [s,setS]=useState<State>(seed);const [ready,setReady]=useState(false);const [role,setRole]=useState('patient');const [auth,setAuth]=useState(false);const [doctorId,setDoctorId]=useState('meera');const [page,setPage]=useState('Overview');const [pageHistory,setPageHistory]=useState<string[]>([]);const [lang,setLang]=useState<Lang>('en');const [theme,setTheme]=useState('system');const [modal,setModal]=useState<Modal>(null);const [profileOpen,setProfileOpen]=useState(false);const [toast,setToast]=useState('');const [query,setQuery]=useState('');const [filter,setFilter]=useState('All');const [metric,setMetric]=useState('Weight');const [range,setRange]=useState('3M');const [table,setTable]=useState(false);const [mobile,setMobile]=useState(false);const [reduced,setReduced]=useState(false);const [large,setLarge]=useState(false);const [contrast,setContrast]=useState(false);const [error,setError]=useState('');const [bookDoctor,setBookDoctor]=useState('meera');const [bookDate,setBookDate]=useState(day(1));const [bookTime,setBookTime]=useState('10:30');const [reason,setReason]=useState('');const [reviewStep,setReviewStep]=useState(false);const [visitTab,setVisitTab]=useState('Overview');const [note,setNote]=useState('');const [followup,setFollowup]=useState('');const [priority,setPriority]=useState('Unassessed');const [priorityReason,setPriorityReason]=useState('');const [online,setOnline]=useState(true);const [specialty,setSpecialty]=useState('All');
