const notify=(message:string)=>setToast(t(message));const go=(name:string)=>{if(name!==page)setPageHistory(prev=>[...prev.slice(-9),page]);setPage(name);setQuery('');setFilter('All');setMobile(false);history.replaceState({},'',`/${role}/${name.toLowerCase().replaceAll(' ','-')}`)};const goBack=()=>{if(pageHistory.length){const target=pageHistory[pageHistory.length-1];setPageHistory(prev=>prev.slice(0,-1));setPage(target);setQuery('');setFilter('All');setMobile(false);history.replaceState({},'',`/${role}/${target.toLowerCase().replaceAll(' ','-')}`);return}setLandingVisible(true);setAuth(false);setMobile(false);history.replaceState({},'','/')};
