const changeVisit=(id:string,patch:Partial<Visit>,event:string)=>setS(prev=>({...prev,visits:prev.visits.map(v=>v.id===id?{...v,...patch,activity:[...v.activity,`${new Date().toLocaleTimeString('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit'})} IST · ${event}`]}:v),notifications:[event,...prev.notifications].slice(0,20)}));
function DoctorLogin(){return <main className="auth-page"><div className="auth-brand"><div className="brand-mark"><HeartPulse size={25}/></div><strong>CareSetu<span>Your story. Better care.</span></strong></div><section className="card auth-card doctor-login-card"><span className="eyebrow">CLINICIAN ACCESS</span><h1>Choose your doctor</h1><p>Select a care team member to open their queue and patient cases.</p><div className="doctor-login-list">{doctors.map(d=><button key={d.id} className={`doctor-login-option ${doctorId===d.id?'selected':''}`} onClick={()=>{setDoctorId(d.id);sessionStorage.setItem('medi-doctor',d.id);sessionStorage.setItem('medi-role','doctor');setAuth(false);go('Overview')}}><span className={`avatar ${d.color}`}>{d.initials}</span><span className="grow"><strong>{d.name}</strong><small>{d.department} · Room {d.room}</small><small>{d.languages}</small></span><ArrowRight size={17}/></button>)}</div><button className="text-button" onClick={()=>{setRole('patient');setAuth(true);history.replaceState({},'', '/auth/patient')}}>Open patient portal <ArrowRight size={14}/></button></section><button className="text-button emergency-text" onClick={()=>open('emergency')}><Phone size={17}/>{t('Emergency help')}</button></main>}
const setAnswer=(value:string)=>setS(prev=>({...prev,answers:{...prev.answers,[patient.id]:{...prev.answers[patient.id],[intakeKeys[step]]:value}}}));
