useEffect(()=>{if(!ready||page!=='AI Case-Taking'||[0,7,8].includes(step))return;const host=document.querySelector('.answer-tools');const textarea=document.querySelector('.intake-main textarea') as HTMLTextAreaElement|null;if(!host||!textarea||host.querySelector('.voice-input-button'))return;const visualizer=document.createElement('div');visualizer.className='voice-guide';visualizer.setAttribute('aria-live','polite');visualizer.innerHTML='<span class="voice-guide-bars" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span><span class="voice-guide-copy">Tap Speak, then say your answer clearly.</span>';host.parentElement?.insertBefore(visualizer,host);const SpeechRecognitionCtor=(window as any).SpeechRecognition||(window as any).webkitSpeechRecognition;const button=document.createElement('button');button.type='button';button.className='voice-input-button';button.setAttribute('aria-label','Speak your answer');button.textContent='🎙️ Speak answer';const note=host.nextElementSibling;if(note?.classList.contains('fine'))note.textContent='Speak naturally or type your answer, then review the editable transcript.';let recognition:any=null;if(!SpeechRecognitionCtor){button.disabled=true;button.title='Voice input is unavailable in this browser';button.textContent='🎙️ Voice unavailable';visualizer.querySelector('.voice-guide-copy')!.textContent='Voice input is unavailable here. Type your answer instead.'}else{recognition=new SpeechRecognitionCtor();recognition.continuous=false;recognition.interimResults=true;recognition.lang=lang==='en'?'en-IN':`${lang}-IN`;recognition.onstart=()=>{button.classList.add('is-listening');visualizer.classList.add('is-listening');visualizer.querySelector('.voice-guide-copy')!.textContent='Listening… speak naturally.';button.textContent='⏹ Stop listening';button.setAttribute('aria-label','Stop listening')};recognition.onresult=(event:any)=>{let transcript='';for(let i=0;i<event.results.length;i++)transcript+=event.results[i][0].transcript;const existing=answers[intakeKeys[step]]||'';setAnswer([existing,transcript].filter(Boolean).join(existing?' ':'').trim())};recognition.onerror=()=>{button.classList.remove('is-listening');visualizer.classList.remove('is-listening');visualizer.querySelector('.voice-guide-copy')!.textContent='Tap Speak, then say your answer clearly.';button.textContent='🎙️ Speak answer';button.setAttribute('aria-label','Speak your answer');notify('Voice input was unavailable. You can type instead.')};recognition.onend=()=>{button.classList.remove('is-listening');visualizer.classList.remove('is-listening');visualizer.querySelector('.voice-guide-copy')!.textContent='Tap Speak, then say your answer clearly.';button.textContent='🎙️ Speak answer';button.setAttribute('aria-label','Speak your answer')};button.onclick=()=>{if(button.classList.contains('is-listening'))recognition.stop();else{try{recognition.start()}catch{notify('Voice input is already starting.')}}}}host.insertBefore(button,host.firstChild);return()=>{try{recognition?.stop()}catch{}button.remove();visualizer.remove()}},[ready,page,step,lang]);
const moveStep=(n:number)=>setS(prev=>({...prev,intakeStep:{...prev.intakeStep,[patient.id]:Math.max(0,Math.min(8,n))}}));
useEffect(()=>{if(!ready||page!=='AI Case-Taking'||step!==2)return;const field=document.querySelector('.intake-main .field');if(!field||field.parentElement?.querySelector('.duration-options'))return;const group=document.createElement('div');group.className='duration-options';group.setAttribute('role','group');group.setAttribute('aria-label','Choose when symptoms started');['1–3 days','3–7 days','7–10 days'].forEach(option=>{const button=document.createElement('button');button.type='button';button.textContent=option;button.className=answers[intakeKeys[step]]===option?'selected':'';button.setAttribute('aria-pressed',String(answers[intakeKeys[step]]===option));button.onclick=()=>{group.querySelectorAll('button').forEach(item=>{item.classList.remove('selected');item.setAttribute('aria-pressed','false')});button.classList.add('selected');button.setAttribute('aria-pressed','true');setAnswer(option);moveStep(step+1)};group.appendChild(button)});field.parentElement?.insertBefore(group,field);const label=field.querySelector('span');if(label)label.textContent='Or type a different duration';return()=>{group.remove()}},[ready,page,step]);
useEffect(()=>{if(!ready||page!=='AI Case-Taking'||![3,4,5].includes(step))return;const field=document.querySelector('.intake-main .field');if(!field||field.parentElement?.querySelector('.clinical-options'))return;const optionSets:Record<number,string[]>={3:['Mild (1–3)','Moderate (4–6)','Severe (7–10)'],4:['No','Yes'],5:['No','Yes']};const group=document.createElement('div');group.className='duration-options clinical-options';group.setAttribute('role','group');group.setAttribute('aria-label','Choose an answer');optionSets[step].forEach(option=>{const button=document.createElement('button');button.type='button';button.textContent=option;button.className=answers[intakeKeys[step]]===option?'selected':'';button.setAttribute('aria-pressed',String(answers[intakeKeys[step]]===option));button.onclick=()=>{group.querySelectorAll('button').forEach(item=>{item.classList.remove('selected');item.setAttribute('aria-pressed','false')});button.classList.add('selected');button.setAttribute('aria-pressed','true');setAnswer(option);moveStep(step+1)};group.appendChild(button)});field.parentElement?.insertBefore(group,field);const label=field.querySelector('span');if(label)label.textContent='Or type a different answer';return()=>{group.remove()}},[ready,page,step]);
useEffect(()=>{if(!ready||page!=='AI Case-Taking'||![3,4,5,6].includes(step))return;const helper=document.querySelector('.intake-main>p');if(!helper)return;helper.textContent=step===3?'Choose a rating, or type a more specific description.':step===4?'Select whether breathing feels difficult right now.':step===5?'Select any warning symptom that applies to you.':'Share known illnesses, medicines, or allergies. You can correct this before submitting.'},[ready,page,step]);
const tokenAction=(v:Visit)=>{if(!isDoctor)return;if(v.token)return;setS(prev=>{const found=prev.visits.find(x=>x.id===v.id)!;if(found.token||found.status!=='checked-in')return prev;const token=`MED-${String(prev.nextToken).padStart(3,'0')}`;return {...prev,nextToken:prev.nextToken+1,visits:prev.visits.map(x=>x.id===v.id?{...x,token,status:'waiting',activity:[...x.activity,`Dr. Meera Sharma assigned ${token}`]}:x),notifications:[`${token} assigned. Please go to room ${room(v.doctorId)}.`,...prev.notifications]}});notify('Token assigned')};
